INSERT INTO blog_posts (slug, title, excerpt, content, category, published_at, read_time_minutes, emoji, author, author_title, source_url, source_name, video_url, created_at, updated_at)
VALUES
('tuoitre-vn-9-dieu-giao-duc-gioi-tinh-giup-con-tre-tuoi-day-thi-1202800-htm', '9 điều giáo dục giới tính giúp trẻ tuổi dậy thì phát triển lành mạnh', 'Giúp con nhận thức đúng về những thay đổi cơ thể, tâm lý và trang bị kỹ năng tự bảo vệ bản thân ở tuổi dậy thì.', 'Tuổi dậy thì là cột mốc quan trọng với sự thay đổi toàn diện về thể chất và cảm xúc. Việc tiếp cận thông tin chính xác từ sớm giúp các em tự tin và an tâm hơn trong hành trình trưởng thành.', 'Sức khỏe', '2026-07-24', 5, '🌱', 'Cố vấn Y khoa EDUcare', 'Chuyên gia tâm lý & sức khỏe vị thành niên', 'https://tuoitre.vn/9-dieu-giao-duc-gioi-tinh-giup-con-tre-tuoi-day-thi-1202800.htm', 'Báo Tuổi Trẻ Online', NULL, NOW(), NOW()),
('benhviennhitrunguong-gov-vn-giao-duc-gioi-tinh-cho-tre-theo-lua-tuoi-van-de-quan', 'Giáo dục giới tính cho trẻ theo lứa tuổi - Vấn đề quan trọng nhưng thường bị bỏ qua', 'Hướng dẫn của các chuyên gia y tế về thời điểm và cách thức đối thoại cởi mở với trẻ theo từng giai đoạn phát triển.', 'Nhiều phụ huynh e ngại việc nói về giới tính với con trẻ, tuy nhiên việc định hướng đúng lứa tuổi giúp phòng tránh nguy cơ xâm hại và định hình nhân cách lành mạnh.', 'Sức khỏe', '2026-07-24', 5, '🏥', 'Bệnh viện Nhi Trung ương', 'Khoa Tâm lý & Sức khỏe Trẻ em', 'https://benhviennhitrunguong.gov.vn/giao-duc-gioi-tinh-cho-tre-theo-lua-tuoi-van-de-quan-trong-nhung-thuong-bi-bo-qua.html', 'Bệnh viện Nhi Trung ương', NULL, NOW(), NOW()),
('hellobacsi-com-nuoi-day-con-tuoi-day-thi-tam-ly-tuoi-day-thi-8-cach-giao-duc-gio', '8 cách giáo dục giới tính cho con ở tuổi dậy thì giúp con tự tin', 'Những gợi ý thực tế và nhân văn giúp thanh thiếu niên hiểu về ranh giới cá nhân, tình bạn và sức khỏe sinh sản.', 'Giáo dục giới tính không chỉ là câu chuyện sinh học mà là hành trang kỹ năng sống giúp trẻ làm chủ cảm xúc, thiết lập ranh giới an toàn và tôn trọng mọi người xung quanh.', 'Kỹ năng sống', '2026-07-24', 5, '🤝', 'Đội ngũ Y tế HelloBacsi', 'Cố vấn thông tin y học cộng đồng', 'https://hellobacsi.com/nuoi-day-con/tuoi-day-thi/tam-ly-tuoi-day-thi/8-cach-giao-duc-gioi-tinh-cho-con/', 'HelloBacsi', NULL, NOW(), NOW()),
('braincare-vn-co-phai-hoc-sinh-thuong-xuyen-gap-van-de-tam-li-nhu-the-nay', 'Những dấu hiệu vấn đề tâm lý học đường thường gặp ở học sinh', 'Nhận diện sớm các biểu hiện mệt mỏi tinh thần, lo âu thi cử và thay đổi thói quen sinh hoạt ở tuổi học trò.', 'Áp lực học tập và các mối quan hệ bạn bè có thể dẫn tới những biến đổi tâm lý bất thường nếu không được lắng nghe và hỗ trợ kịp thời.', 'Tinh thần', '2026-07-24', 5, '🧠', 'Trung tâm Tham vấn Tâm lý BrainCare', 'Đội ngũ chuyên gia tâm lý lâm sàng', 'https://braincare.vn/co-phai-hoc-sinh-thuong-xuyen-gap-van-de-tam-li-nhu-the-nay/', 'BrainCare Vietnam', NULL, NOW(), NOW()),
('nhathuoclongchau-com-vn-bai-viet-stress-tuoi-day-thi-la-gi-lam-the-nao-de-cai-th', 'Stress tuổi dậy thì là gì? Làm thế nào để nhận biết và cải thiện?', 'Phân tích khoa học về căng thẳng thần kinh lứa tuổi 12-18 và thói quen giải tỏa áp lực hiệu quả.', 'Stress ở tuổi dậy thì đến từ sự biến động nội tiết tố kết hợp với áp lực điểm số. Vận động thể thao, ngủ đúng giờ và chia sẻ cảm xúc là chìa khóa duy trì năng lượng tích cực.', 'Tinh thần', '2026-07-24', 5, '💊', 'Dược sĩ Chuyên môn Long Châu', 'Hệ thống thông tin y khoa & dược phẩm', 'https://nhathuoclongchau.com.vn/bai-viet/stress-tuoi-day-thi-la-gi-lam-the-nao-de-cai-thien.html', 'Nhà thuốc Long Châu', NULL, NOW(), NOW()),
('vinmec-com-vie-bai-viet-tam-ly-tre-day-thi-rat-phuc-tap-cha-me-can-kien-nhan-vi', 'Tâm lý trẻ tuổi dậy thì rất phức tạp - Cha mẹ và học sinh cần kiên nhẫn', 'Tìm hiểu tâm lý khủng hoảng tuổi dậy thì dưới góc nhìn y khoa hiện đại để tạo sự thấu hiểu gia đình.', 'Tuổi dậy thì là giai đoạn định hình bản ngộ cá nhân. Học sinh dễ nhạy cảm và cần không gian riêng, đòi hỏi sự kiên nhẫn lắng nghe từ người lớn.', 'Tinh thần', '2026-07-24', 5, '🩺', 'Bệnh viện Đa khoa Quốc tế Vinmec', 'Chuyên khoa Nhi & Tâm lý hành vi', 'https://www.vinmec.com/vie/bai-viet/tam-ly-tre-day-thi-rat-phuc-tap-cha-me-can-kien-nhan-vi', 'Vinmec Healthcare System', NULL, NOW(), NOW()),
('tytphuongphuthohoa-medinet-gov-vn-chuyen-muc-hay-quan-tam-de-khong-co-bien-doi-t', 'Hãy quan tâm để không có biến đổi tâm lý tiêu cực tuổi dậy thì', 'Khuyến cáo y tế cộng đồng về chăm sóc sức khỏe tinh thần và kỹ năng quản lý cảm xúc lứa tuổi học sinh.', 'Chăm sóc sức khỏe tinh thần tuổi dậy thì đóng vai trò quyết định tới sự phát triển thể chất và tinh thần bền vững trong tương lai.', 'Sức khỏe', '2026-07-24', 5, '❤️', 'Trạm Y tế Phú Thọ Hòa', 'Trung tâm Y tế Quảng bá Sức khỏe Cộng đồng', 'https://tytphuongphuthohoa.medinet.gov.vn/chuyen-muc/hay-quan-tam-de-khong-co-bien-doi-tam-ly-tieu-cuc-tuoi-day-thi-cmobile17015-225750.aspx', 'Medinet Thành phố Hồ Chí Minh', NULL, NOW(), NOW()),
('moet-congtacxahoi-tuvantamly-edu-vn-2025-06-23-ky-nang-ung-pho-voi-cang-thang-tr', 'Kỹ năng ứng phó với căng thẳng trong học tập và thi cử cho học sinh', 'Cẩm nang phương pháp quản lý thời gian, ôn thi khoa học và giữ vững tâm lý trước các kỳ thi quan trọng.', 'Thi cử là thử thách tâm lý lớn đối với mọi học sinh. Áp dụng kỹ thuật hít thở sâu, chia nhỏ mục tiêu học tập giúp duy trì sự bình tĩnh và tập trung tối đa.', 'Học tập', '2026-07-24', 5, '📚', 'Cổng Tư vấn Tâm lý Học đường', 'Bộ Giáo dục và Đào tạo (MOET)', 'https://moet-congtacxahoi-tuvantamly.edu.vn/2025/06/23/ky-nang-ung-pho-voi-cang-thang-trong-hoc-tap-va-thi-cu-cho-moi-hoc-sinh/', 'Bộ Giáo dục và Đào tạo (MOET)', NULL, NOW(), NOW()),
('vov-vn-xa-hoi-ap-luc-hoc-tap-sat-thu-vo-hinh-cua-suc-khoe-tinh-than-hoc-sinh-pos', 'Áp lực học tập: Sát thủ vô hình của sức khỏe tinh thần học sinh', 'Bài phân tích chuyên sâu của PGS.TS. Trần Thành Nam về thực trạng áp lực điểm số và giải pháp nâng cao sức bền tinh thần cho thế hệ trẻ.', 'Áp lực học tập và kỳ vọng quá lớn từ gia đình, trường học đang trở thành một sát thủ vô hình ảnh hưởng nghiêm trọng đến sức khỏe tinh thần của học sinh.\n\nPGS.TS. Trần Thành Nam nhấn mạnh tầm quan trọng của việc lắng nghe, thấu hiểu, giảm bớt gánh nặng thành tích và tạo không gian cởi mở cho trẻ phát triển toàn diện kỹ năng sống.', 'Chuyên gia chia sẻ', '2026-07-24', 5, '🎓', 'PGS.TS. Trần Thành Nam', 'Chủ nhiệm Khoa Các khoa học Giáo dục, Trường Đại học Giáo dục (ĐHQG Hà Nội)', 'https://vov.vn/xa-hoi/ap-luc-hoc-tap-sat-thu-vo-hinh-cua-suc-khoe-tinh-than-hoc-sinh-post1213514.vov', 'Báo Điện tử VOV.VN', NULL, NOW(), NOW()),
('kinhdoanhvagiaoduc-com-gen-z-khung-hoang-tam-ly-hoc-duong-hay-lang-nghe-truoc-kh', 'Gen Z khủng hoảng tâm lý học đường: Hãy lắng nghe trước khi quá muộn', 'Phân tích tham vấn của TS. Nguyễn Hữu Long về thực trạng khủng hoảng cảm xúc lứa tuổi Gen Z và giải pháp hàn gắn giao tiếp gia đình.', 'TS. Tâm lý Nguyễn Hữu Long nhấn mạnh sự kiên nhẫn lắng nghe, tạo môi trường an toàn không phán xét để đồng hành cùng học sinh vượt qua khủng hoảng tâm lý học đường.', 'Chuyên gia chia sẻ', '2026-07-24', 5, '💡', 'Tiến sĩ Tâm lý Nguyễn Hữu Long', 'Giảng viên trường Đại học Mở TP.HCM', 'https://kinhdoanhvagiaoduc.com/gen-z-khung-hoang-tam-ly-hoc-duong-hay-lang-nghe-truoc-khi-qua-muon', 'Kinh doanh & Giáo dục', NULL, NOW(), NOW()),
('baodongnai-com-vn-dong-nai-cuoi-tuan-202604-cham-soc-suc-khoe-tinh-than-cho-tre-', 'Chăm sóc sức khỏe tinh thần cho trẻ tuổi dậy thì', 'Khuyến nghị chuyên môn về các thói quen nuôi dưỡng đời sống tinh thần khỏe mạnh và cân bằng cảm xúc lứa tuổi vị thành niên.', 'Chăm sóc sức khỏe tinh thần ở tuổi dậy thì là hành trình liên tục cần sự chủ động từ bản thân học sinh và sự hỗ trợ kịp thời từ môi trường xung quanh.', 'Sức khỏe', '2026-07-24', 5, '🌿', 'Ban Biên tập Báo Đồng Nai', 'Chuyên mục Sức khỏe & Cuộc sống', 'https://baodongnai.com.vn/dong-nai-cuoi-tuan/202604/cham-soc-suc-khoe-tinh-than-cho-tre-tuoi-day-thi-0f9258a/', 'Báo Đồng Nai', NULL, NOW(), NOW()),
('youtube-com-shorts-xrbjpqdue-w', 'Short Video: Giải đáp thắc mắc tâm lý & thay đổi cơ thể tuổi dậy thì', 'Video ngắn minh họa trực quan những thay đổi tự nhiên của cơ thể và lời khuyên tự tin cho các bạn trẻ.', 'Xem video trực tiếp với trình phát tương tác trên nền tảng EDUcare.', 'Video chia sẻ', '2026-07-24', 2, '🎬', 'Kênh Video EDUcare', 'Trích dẫn video ngắn giáo dục', 'https://youtube.com/shorts/xrBJpQdUE_w', 'YouTube Shorts - Sức Khỏe Teen', 'https://www.youtube.com/embed/xrBJpQdUE_w', NOW(), NOW()),
('youtube-com-shorts-tr2eelgqr2w', 'Short Video: Mẹo kiểm soát cảm xúc tiêu cực và xả stress nhanh khi học tập', 'Hướng dẫn 3 bước đơn giản giúp bạn giải tỏa áp lực thi cử và duy trì tinh thần thoải mái.', 'Xem video trực tiếp với trình phát tương tác trên nền tảng EDUcare.', 'Video chia sẻ', '2026-07-24', 2, '🎥', 'Kênh Video EDUcare', 'Trích dẫn video ngắn giáo dục', 'https://youtube.com/shorts/TR2eeLGqR2w', 'YouTube Shorts - Tham Vấn Học Đường', 'https://www.youtube.com/embed/TR2eeLGqR2w', NOW(), NOW()),
('youtube-com-shorts-g9gs-56kc6c', 'Short Video: 3 nguyên tắc bảo vệ bản thân an toàn trên không gian mạng', 'Kỹ năng bảo mật thông tin cá nhân và ứng xử thông minh trước các nguy cơ lừa đảo trực tuyến.', 'Xem video trực tiếp với trình phát tương tác trên nền tảng EDUcare.', 'Video chia sẻ', '2026-07-24', 2, '🛡️', 'Kênh Video EDUcare', 'Trích dẫn video ngắn giáo dục', 'https://youtube.com/shorts/G9Gs_56kc6c', 'YouTube Shorts - Cyber Safety', 'https://www.youtube.com/embed/G9Gs_56kc6c', NOW(), NOW()),
('youtube-com-shorts-lcu6k1fegi4', 'Short Video: Kỹ năng quản lý thời gian & tự học hiệu quả cho học sinh', 'Phương pháp chia nhỏ mục tiêu và duy trì động lực học tập tự giác mỗi ngày.', 'Xem video trực tiếp với trình phát tương tác trên nền tảng EDUcare.', 'Video chia sẻ', '2026-07-24', 2, '⚡', 'Kênh Video EDUcare', 'Trích dẫn video ngắn giáo dục', 'https://youtube.com/shorts/lCu6k1fegI4', 'YouTube Shorts - Kỹ Năng Học Tập', 'https://www.youtube.com/embed/lCu6k1fegI4', NOW(), NOW())
INSERT INTO community_posts (author_name, anonymous, content, likes_count, created_at, category_id, title, pinned)
VALUES
('Minh_Khue99', 0, 'Mọi người ơi, khi học bài đêm hay bị mệt mỏi và mất tập trung thì nên làm gì để lấy lại tỉnh táo ạ?', 12, NOW() - INTERVAL 2 DAY, 1, 'Cách lấy lại tập trung khi ôn thi ban đêm?', 0),
('Hoang_Anh_Teen', 0, 'Làm sao để mở lời tâm sự với bố mẹ về những áp lực học tập và định hướng thi cấp 3 vậy mọi người?', 18, NOW() - INTERVAL 1 DAY, 2, 'Làm sao để tâm sự với bố mẹ về áp lực học tập?', 1),
('Bao_An_Quiet', 1, 'Có ai từng bị áp lực đồng lứa (peer pressure) chưa ạ? Thấy bạn bè xung quanh ai cũng giỏi giang...', 25, NOW() - INTERVAL 12 HOUR, 2, 'Cảm giác tự ti khi so sánh bản thân với bạn bè', 0),
('Khanh_Linh_11', 0, 'Trắc nghiệm tình huống trên web EDUcare có đúng thực tế không mọi người? Mình vừa chơi thử game Red Flag Hunt thấy khá thú vị.', 15, NOW() - INTERVAL 4 HOUR, 3, 'Trải nghiệm Mini Game Red Flag Hunt trên EDUcare', 0);